  const normaliseFieldLabel=value=>String(value||'')
    .replace(/\*/g,'')
    .replace(/\s+/g,' ')
    .trim();

  const formFieldKey=(moduleName,label)=>`${moduleName}::${normaliseFieldLabel(label)}`;

