        const win=window.open(url,'_blank','noopener');
        if(!win){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.download=media.filename||'';a.click()}
        setTimeout(()=>URL.revokeObjectURL(url),120000);
